// UncheckableFixtures.swift
// PGPonyCoreTests
//
// 8.4.0 build 7 (plan K4): keys whose self-signatures this device cannot
// check, for the pin, fail-closed and refresh tests. DSA and brainpool
// verify since build 7, so these are secp256k1 keys (ECDSA primary, ECDH
// subkey), which GnuPG makes and PGPony has no verifier for.
//
// `contact*` and `refresh*` were made with gpg 2.2.27 in a throwaway home.
// The Bad copies have one octet of the new signature's last MPI changed
// (gpg reports each as a bad signature); Exp is the primary's User ID
// self-certification renewed with a two-year expiry (gpg
// --quick-set-expire), Subexp the subkey binding renewed the same way,
// Uid adds a second User ID, DirectBad adds a direct-key signature (0x1F)
// made from the User ID certification with its type changed and an octet
// altered. Each variant is the Base ring with only that signature added or
// replaced, as `gpg --export` gives it.

import Foundation

nonisolated enum UncheckableFixtures {

    /// gpg 2.4.4, from the Android repo's test resources
    /// (keys/bindings/gpg-secp256k1.pgp): ECDSA primary, User ID, ECDH
    /// subkey, ECDSA signing subkey with its back-signature.
    static let androidSecp256k1 = Data(base64Encoded: "")!

    /// A primary, its User ID and one ECDH subkey.
    static let contact = Data(base64Encoded: "")!
    /// The same key with a second ECDH subkey whose binding has one changed octet.
    static let contactWithAlteredSecondBinding = Data(base64Encoded: "")!

    /// A primary, its User ID and one ECDH subkey.
    static let refreshBase = Data(base64Encoded: "")!
    /// Base plus a second User ID whose certification has one changed octet.
    static let refreshUidBad = Data(base64Encoded: "")!
    /// Base with the renewed (two-year) User ID certification, one octet changed.
    static let refreshExpBad = Data(base64Encoded: "")!
    /// Base with the renewed (two-year) subkey binding, one octet changed.
    static let refreshSubexpBad = Data(base64Encoded: "")!
    /// Base plus an altered direct-key signature.
    static let refreshDirectBad = Data(base64Encoded: "")!
    /// Base with the genuine renewed User ID certification (two-year expiry).
    static let refreshExp = Data(base64Encoded: "")!
    /// Base with the genuine renewed subkey binding (two-year expiry).
    static let refreshSubexp = Data(base64Encoded: "")!
}
